node --input-type=module <<'NODE'
import assert from 'node:assert/strict';
import { mergeLayers } from './src/merge.mjs';
import { loadConfig } from './src/config.mjs';
const defaults = { endpoint: '/default', retries: 3, flags: { enabled: true, count: 4 }, list: [{ value: 1 }], untouched: { nested: ['x'] } };
const environment = { endpoint: '', retries: 0, flags: { enabled: false, count: undefined }, list: [null] };
const overrides = { endpoint: null, retries: undefined, flags: { count: 0 }, list: undefined };
const merged = mergeLayers(defaults, environment, overrides);
assert.deepEqual(merged, { endpoint: null, retries: 0, flags: { enabled: false, count: 0 }, list: [null], untouched: { nested: ['x'] } });
assert.notEqual(merged.flags, defaults.flags);
assert.notEqual(merged.untouched, defaults.untouched);
assert.notEqual(merged.untouched.nested, defaults.untouched.nested);
merged.flags.enabled = 'changed';
merged.list[0] = 'changed';
merged.untouched.nested.push('changed');
assert.equal(defaults.flags.enabled, true);
assert.equal(environment.list[0], null);
assert.deepEqual(defaults.untouched.nested, ['x']);
const special = mergeLayers(JSON.parse('{"__proto__":{"safe":true},"constructor":{"x":1}}'));
assert.equal(Object.hasOwn(special, '__proto__'), true);
assert.equal(special.safe, undefined);
assert.deepEqual(special.constructor, { x: 1 });
const cfg = loadConfig({ endpoint: '/ok', retries: 2 }, {}, { endpoint: '', retries: 0 });
assert.deepEqual(cfg, { endpoint: '', retries: 0 });
for (const bad of [
  () => loadConfig({ endpoint: 2, retries: 0 }),
  () => loadConfig({ endpoint: '/ok', retries: -1 }),
  () => loadConfig({ endpoint: '/ok', retries: 1.2 }),
]) assert.throws(bad);
console.log('additional contract checks passed');
