function isPlain(value) {
  if (value === null || typeof value !== 'object') return false;
  const prototype = Object.getPrototypeOf(value);
  return prototype === Object.prototype || prototype === null;
}

function copyProperties(source, target, seen, shouldSkip = () => false, skipUndefined = false) {
  for (const key of Reflect.ownKeys(source)) {
    if (shouldSkip(key)) continue;
    const descriptor = Object.getOwnPropertyDescriptor(source, key);
    if (!descriptor) continue;
    const propertyValue = source[key];
    if (skipUndefined && propertyValue === undefined) continue;
    Object.defineProperty(target, key, {
      value: cloneValue(propertyValue, seen),
      enumerable: descriptor.enumerable,
      writable: true,
      configurable: true,
    });
  }
}

function cloneValue(value, seen = new WeakMap()) {
  if (value === null || typeof value !== 'object') return value;
  if (seen.has(value)) return seen.get(value);

  let copy;
  if (Array.isArray(value)) {
    copy = new Array(value.length);
  } else if (value instanceof Date) {
    copy = new Date(value.getTime());
  } else if (value instanceof RegExp) {
    copy = new RegExp(value.source, value.flags);
    copy.lastIndex = value.lastIndex;
  } else if (value instanceof Map) {
    copy = new Map();
    seen.set(value, copy);
    for (const [key, entry] of value) copy.set(cloneValue(key, seen), cloneValue(entry, seen));
  } else if (value instanceof Set) {
    copy = new Set();
    seen.set(value, copy);
    for (const entry of value) copy.add(cloneValue(entry, seen));
  } else if (value instanceof ArrayBuffer) {
    copy = value.slice(0);
  } else if (typeof SharedArrayBuffer !== 'undefined' && value instanceof SharedArrayBuffer) {
    copy = new SharedArrayBuffer(value.byteLength);
    new Uint8Array(copy).set(new Uint8Array(value));
  } else if (ArrayBuffer.isView(value)) {
    const buffer = cloneValue(value.buffer, seen);
    copy = value instanceof DataView
      ? new DataView(buffer, value.byteOffset, value.byteLength)
      : new value.constructor(buffer, value.byteOffset, value.length);
  } else {
    copy = Object.create(Object.getPrototypeOf(value));
  }

  seen.set(value, copy);
  copyProperties(value, copy, seen, (key) =>
    (Array.isArray(value) && key === 'length') ||
    (value instanceof RegExp && key === 'lastIndex') ||
    (ArrayBuffer.isView(value) && typeof key === 'string' && /^(0|[1-9][0-9]*)$/.test(key)),
    isPlain(value)
  );
  return copy;
}

function defineValue(target, key, value) {
  Object.defineProperty(target, key, {
    value,
    enumerable: true,
    writable: true,
    configurable: true,
  });
}

function mergeObjects(base, overlay) {
  const result = cloneValue(base);
  for (const [key, value] of Object.entries(overlay)) {
    if (value === undefined) continue;
    const current = Object.prototype.hasOwnProperty.call(result, key) ? result[key] : undefined;
    const merged = isPlain(value) && isPlain(current)
      ? mergeObjects(current, value)
      : cloneValue(value);
    defineValue(result, key, merged);
  }
  return result;
}

export function mergeLayers(...layers) {
  const result = {};
  for (const layer of layers) {
    for (const [key, value] of Object.entries(layer)) {
      if (value === undefined) continue;
      const current = Object.prototype.hasOwnProperty.call(result, key) ? result[key] : undefined;
      const merged = isPlain(value) && isPlain(current)
        ? mergeObjects(current, value)
        : cloneValue(value);
      defineValue(result, key, merged);
    }
  }
  return result;
}
